contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a1, address a2) public payable {
        uint256 before1 = c.balances(a1); if (__ESBMC_reverted()) return;
        uint256 before2 = c.balances(a2); if (__ESBMC_reverted()) return;
        uint256 beforeSelf = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 after1 = c.balances(a1); if (__ESBMC_reverted()) return;
        uint256 after2 = c.balances(a2); if (__ESBMC_reverted()) return;
        uint256 afterSelf = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert((after1 == before1 || after1 == 0) &&
               (after2 == before2 || after2 == 0) &&
               (afterSelf == beforeSelf || afterSelf == 0));
    }

    receive() external payable {}
}

